package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.io.TempDir;

/**
 * M-F6: grammar-directed differential fuzzing with minimization over this pass's promoted surfaces — general paths
 * (compound/negated/zero-or-one), value-guarded VALUES, translated filters, aggregates over expressions, COUNT(DISTINCT
 * *) and ORDER BY expressions. Queries are generated as clause lists from a fixed seed; every query runs on both arms
 * (native vs {@code rdf4j.lmdb.nativeQueryEngine.enabled=false}) and compares result multisets. On a mismatch the
 * harness greedily removes clauses while the mismatch persists and reports the minimized query with the seed.
 * Complements {@code LmdbNativeDifferentialFuzzTest}, which owns the BGP/kernel shapes.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class LmdbNativePromotionFuzzTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final long SEED = 20260818L;
	private static final int QUERIES_PER_SHAPE = 25;

	@TempDir
	static File dataDir;

	private SailRepository repository;

	@BeforeAll
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		Random random = new Random(SEED);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI[] nodes = new IRI[12];
			for (int i = 0; i < nodes.length; i++) {
				nodes[i] = vf.createIRI(EX, "n" + i);
			}
			IRI[] predicates = { vf.createIRI(EX, "p"), vf.createIRI(EX, "q"), vf.createIRI(EX, "r") };
			for (int i = 0; i < 40; i++) {
				IRI subject = nodes[random.nextInt(nodes.length)];
				IRI predicate = predicates[random.nextInt(predicates.length)];
				switch (random.nextInt(4)) {
				case 0 -> conn.add(subject, predicate, nodes[random.nextInt(nodes.length)]);
				case 1 -> conn.add(subject, predicate, vf.createLiteral(random.nextInt(10)));
				case 2 -> conn.add(subject, predicate, vf.createLiteral("t" + random.nextInt(4)));
				default -> conn.add(subject, predicate, vf.createLiteral("x", random.nextBoolean() ? "en" : "EN"));
				}
			}
			conn.commit();
		}
	}

	@AfterAll
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private List<BindingSet> rows(String query, boolean nativeEngine) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEngine));
			try (SailRepositoryConnection conn = repository.getConnection()) {
				return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			}
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private boolean mismatches(String header, List<String> clauses) {
		String query = assemble(header, clauses);
		List<BindingSet> generic;
		List<BindingSet> nativeRows;
		try {
			generic = rows(query, false);
			nativeRows = rows(query, true);
		} catch (RuntimeException e) {
			throw new AssertionError("evaluation failed (seed " + SEED + "):\n" + query, e);
		}
		if (nativeRows.size() != generic.size()) {
			return true;
		}
		List<BindingSet> remaining = new ArrayList<>(generic);
		for (BindingSet row : nativeRows) {
			if (!remaining.remove(row)) {
				return true;
			}
		}
		return false;
	}

	private static String assemble(String header, List<String> clauses) {
		return header.replace("%WHERE%", String.join(" ", clauses));
	}

	/** Differential check with greedy clause minimization on mismatch. */
	private void checkMinimized(String header, List<String> clauses) {
		if (!mismatches(header, clauses)) {
			return;
		}
		List<String> minimal = new ArrayList<>(clauses);
		boolean shrunk = true;
		while (shrunk && minimal.size() > 1) {
			shrunk = false;
			for (int i = 0; i < minimal.size(); i++) {
				List<String> candidate = new ArrayList<>(minimal);
				candidate.remove(i);
				try {
					if (mismatches(header, candidate)) {
						minimal = candidate;
						shrunk = true;
						break;
					}
				} catch (AssertionError ignored) {
					// a candidate that fails to parse/evaluate is not a valid minimization step
				}
			}
		}
		throw new AssertionError("native vs generic mismatch (seed " + SEED + "), minimized query:\n"
				+ assemble(header, minimal));
	}

	private String pattern(Random random, String subjectVar, String objectVar) {
		String predicate = new String[] { "p", "q", "r" }[random.nextInt(3)];
		return subjectVar + " <" + EX + predicate + "> " + objectVar + " .";
	}

	private String pathClause(Random random, String subjectVar, String objectVar) {
		switch (random.nextInt(5)) {
		case 0:
			return subjectVar + " (<" + EX + "p>/<" + EX + "q>)+ " + objectVar + " .";
		case 1:
			return subjectVar + " !<" + EX + "p>+ " + objectVar + " .";
		case 2:
			return subjectVar + " !(<" + EX + "p>|^<" + EX + "q>)+ " + objectVar + " .";
		case 3:
			return subjectVar + " <" + EX + "p>? " + objectVar + " .";
		default:
			return subjectVar + " (<" + EX + "q>/<" + EX + "r>)* " + objectVar + " .";
		}
	}

	private String filterClause(Random random, String var) {
		switch (random.nextInt(4)) {
		case 0:
			return "FILTER(!(" + var + " > 2 && " + var + " < 7))";
		case 1:
			return "FILTER(" + var + " + 1 < 6)";
		case 2:
			return "FILTER(" + var + " = 3 || " + var + " > 8)";
		default:
			return "FILTER(BOUND(" + var + "))";
		}
	}

	@Test
	public void promotedPathShapes() {
		Random random = new Random(SEED + 1);
		for (int i = 0; i < QUERIES_PER_SHAPE; i++) {
			List<String> clauses = new ArrayList<>();
			clauses.add(pattern(random, "?s", "?o"));
			clauses.add(pathClause(random, "?s", "?x"));
			if (random.nextBoolean()) {
				clauses.add("OPTIONAL { " + pattern(random, "?x", "?y") + " }");
			}
			checkMinimized("SELECT * WHERE { %WHERE% }", clauses);
		}
	}

	@Test
	public void translatedFilterShapes() {
		Random random = new Random(SEED + 2);
		for (int i = 0; i < QUERIES_PER_SHAPE; i++) {
			List<String> clauses = new ArrayList<>();
			clauses.add(pattern(random, "?s", "?v"));
			if (random.nextBoolean()) {
				clauses.add(pattern(random, "?s", "?w"));
			}
			clauses.add(filterClause(random, "?v"));
			checkMinimized("SELECT * WHERE { %WHERE% }", clauses);
		}
	}

	@Test
	public void valueGuardedValuesShapes() {
		Random random = new Random(SEED + 3);
		for (int i = 0; i < QUERIES_PER_SHAPE; i++) {
			List<String> clauses = new ArrayList<>();
			String values = random.nextBoolean() ? "VALUES ?v { \"x\"@en }"
					: "VALUES ?v { " + random.nextInt(10) + " }";
			clauses.add(values);
			clauses.add(pattern(random, "?s", "?v"));
			if (random.nextBoolean()) {
				clauses.add(pattern(random, "?s", "?o"));
			}
			checkMinimized("SELECT * WHERE { %WHERE% }", clauses);
		}
	}

	@Test
	public void promotedAggregateShapes() {
		Random random = new Random(SEED + 4);
		for (int i = 0; i < QUERIES_PER_SHAPE; i++) {
			List<String> clauses = new ArrayList<>();
			clauses.add(pattern(random, "?s", "?v"));
			if (random.nextBoolean()) {
				clauses.add("OPTIONAL { " + pattern(random, "?s", "?w") + " }");
			}
			// GROUP_CONCAT is excluded: its declared order policy leaves the concatenation order unspecified,
			// so the two arms may legitimately produce different strings
			String header = switch (random.nextInt(4)) {
			case 0 -> "SELECT (COUNT(DISTINCT *) AS ?c) WHERE { %WHERE% }";
			case 1 -> "SELECT (SUM(?v + 1) AS ?c) WHERE { %WHERE% }";
			case 2 -> "SELECT ?s (COUNT(DISTINCT STR(?v)) AS ?c) WHERE { %WHERE% } GROUP BY ?s";
			default -> "SELECT (MIN(?v * 2) AS ?c) WHERE { %WHERE% }";
			};
			checkMinimized(header, clauses);
		}
	}

	@Test
	public void minOverComputedExpressionMatchesGenericForSeedFixture() {
		String projectionQuery = "SELECT ?v (?v * 2 AS ?twice) WHERE { ?s <" + EX + "p> ?v . }";
		List<BindingSet> projectedGeneric = rows(projectionQuery, false);
		assertThat(rows(projectionQuery, true))
				.as("native arithmetic rows must equal generic rows %s", projectedGeneric)
				.containsExactlyInAnyOrderElementsOf(projectedGeneric);
		String query = "SELECT (MIN(?v * 2) AS ?c) WHERE { ?s <" + EX + "p> ?v . }";
		List<BindingSet> generic = rows(query, false);
		assertThat(rows(query, true))
				.as("native MIN result must equal generic result %s", generic)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	/** ORDER BY expressions: multiset differential (ties leave inter-row order unspecified). */
	@Test
	public void orderByExpressionShapes() {
		Random random = new Random(SEED + 5);
		for (int i = 0; i < QUERIES_PER_SHAPE; i++) {
			List<String> clauses = new ArrayList<>();
			clauses.add(pattern(random, "?s", "?v"));
			String direction = random.nextBoolean() ? "DESC(?v * 2)" : "(?v + 1)";
			checkMinimized("SELECT ?s WHERE { %WHERE% } ORDER BY " + direction, clauses);
		}
	}

}
